#!/usr/bin/env python
"""Build HuggingFace tokenized datasets from LAMAR-m6A split CSV files.

This script is the cleaned GitHub version of the old notebook code:

    CSV train/valid/test splits
      -> AutoTokenizer(single_nucleotide)
      -> DatasetDict saved with save_to_disk(...)

It supports both sequence modes:

    full   : data/processed/full_splits/
    mature : data/processed/mature_splits/
"""

from __future__ import annotations

import argparse
import multiprocessing as mp
from pathlib import Path


DEFAULT_CELL_LINES = ["a549", "cd8t", "hek293", "hela", "molm13"]
DEFAULT_LENGTHS = [51, 101, 201, 401, 801, 1601]
DEFAULT_SPLITS = ["train", "valid", "test"]


def parse_csv_name(path: Path, cell_lines: list[str], lengths: list[int], splits: list[str]) -> tuple[str, str, int] | None:
    """Return (split, cell, length) if a split CSV name matches the expected pattern."""
    name = path.name
    for split in splits:
        for cell in cell_lines:
            for length in lengths:
                expected = f"{split}_m6a_full_{cell}_{length}.csv"
                if name == expected:
                    return split, cell, length
    return None


def discover_split_csvs(
    split_dir: Path,
    cell_lines: list[str],
    lengths: list[int],
    splits: list[str],
) -> dict[tuple[str, int], dict[str, Path]]:
    groups: dict[tuple[str, int], dict[str, Path]] = {}
    for csv_path in sorted(split_dir.glob("*.csv")):
        parsed = parse_csv_name(csv_path, cell_lines, lengths, splits)
        if parsed is None:
            continue
        split, cell, length = parsed
        groups.setdefault((cell, length), {})[split] = csv_path
    return groups


def tokenize_batch(examples, tokenizer, length: int):
    tokenized = tokenizer(
        examples["seq"],
        max_length=length + 2,
        truncation=True,
    )
    tokenized["labels"] = examples["label"]
    return tokenized


def build_one_dataset(
    data_files: dict[str, Path],
    output_path: Path,
    tokenizer_path: Path,
    length: int,
    num_proc: int,
    overwrite: bool,
) -> None:
    from datasets import load_dataset
    from transformers import AutoTokenizer

    if output_path.exists() and not overwrite:
        print(f"skip existing: {output_path}")
        return

    tokenizer = AutoTokenizer.from_pretrained(
        tokenizer_path,
        model_max_length=length + 2,
    )

    dataset = load_dataset(
        "csv",
        data_files={split: str(path) for split, path in data_files.items()},
    )

    # Split CSV files are generated by the same pipeline, so columns should match.
    remove_columns = dataset[next(iter(dataset.keys()))].column_names
    processed = dataset.map(
        lambda examples: tokenize_batch(examples, tokenizer, length),
        batched=True,
        num_proc=num_proc,
        remove_columns=remove_columns,
    )

    output_path.parent.mkdir(parents=True, exist_ok=True)
    processed.save_to_disk(output_path, num_proc=num_proc)
    print(f"saved: {output_path}")


def mode_paths(data_dir: Path, mode: str) -> tuple[Path, Path]:
    if mode == "full":
        return data_dir / "processed" / "full_splits", Path("dataset") / "full"
    if mode == "mature":
        return data_dir / "processed" / "mature_splits", Path("dataset") / "mature"
    raise ValueError(f"Unknown mode: {mode}")


def build_mode(args, mode: str) -> None:
    split_dir, output_base_dir = mode_paths(args.data_dir, mode)
    if args.split_dir is not None:
        split_dir = args.split_dir
    if args.output_dir is not None:
        output_base_dir = args.output_dir / mode if args.mode == "both" else args.output_dir

    if not split_dir.exists():
        raise FileNotFoundError(f"Split CSV directory not found: {split_dir}")

    groups = discover_split_csvs(split_dir, args.cell_lines, args.lengths, args.splits)
    if not groups:
        print(f"no matching CSV files found in {split_dir}")
        return

    for (cell, length), files in sorted(groups.items()):
        missing = [split for split in args.splits if split not in files]
        if missing:
            print(f"skip incomplete group: {mode} {cell} {length}; missing {missing}")
            continue

        dataset_name = f"m6a_{mode}_{cell}_{length}"
        output_path = output_base_dir / dataset_name

        print(f"processing: mode={mode} cell={cell} length={length}")
        for split in args.splits:
            print(f"  {split}: {files[split]}")
        print(f"  output: {output_path}")

        build_one_dataset(
            data_files={split: files[split] for split in args.splits},
            output_path=output_path,
            tokenizer_path=args.tokenizer_path,
            length=length,
            num_proc=args.num_proc,
            overwrite=args.overwrite,
        )


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--data-dir", type=Path, default=Path("data"))
    parser.add_argument("--tokenizer-path", type=Path, default=Path("tokenizer/single_nucleotide"))
    parser.add_argument("--mode", choices=["full", "mature", "both"], default="both")
    parser.add_argument("--cell-lines", nargs="+", default=DEFAULT_CELL_LINES)
    parser.add_argument("--lengths", nargs="+", type=int, default=DEFAULT_LENGTHS)
    parser.add_argument("--splits", nargs="+", default=DEFAULT_SPLITS)
    parser.add_argument("--split-dir", type=Path, default=None, help="Override input split CSV directory.")
    parser.add_argument("--output-dir", type=Path, default=None, help="Override output tokenized dataset directory.")
    parser.add_argument("--num-proc", type=int, default=mp.cpu_count())
    parser.add_argument("--overwrite", action="store_true")
    args = parser.parse_args()

    if not args.tokenizer_path.exists():
        raise FileNotFoundError(f"Tokenizer path not found: {args.tokenizer_path}")

    modes = ["full", "mature"] if args.mode == "both" else [args.mode]
    for mode in modes:
        build_mode(args, mode)


if __name__ == "__main__":
    main()
